code.java:
public String dayOfProgrammer(int year) {
    int feb;
    if (year == 1918) {
        feb = 15;                                  // transition year
    } else if (year < 1918) {
        feb = (year % 4 == 0) ? 29 : 28;           // Julian
    } else {
        boolean leap = year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);
        feb = leap ? 29 : 28;                      // Gregorian
    }
    int[] days = {31, feb, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    int remaining = 256, month = 0;
    while (remaining > days[month]) {
        remaining -= days[month];
        month++;
    }
    return String.format("%02d.%02d.%d", remaining, month + 1, year);
}

code.python:
def dayOfProgrammer(year: int) -> str:
    if year == 1918:
        feb = 15                                   # transition year
    elif year < 1918:
        feb = 29 if year % 4 == 0 else 28          # Julian
    else:
        leap = year % 400 == 0 or (year % 4 == 0 and year % 100 != 0)
        feb = 29 if leap else 28                   # Gregorian
    days = [31, feb, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    remaining, month = 256, 0
    while remaining > days[month]:
        remaining -= days[month]
        month += 1
    return f"{remaining:02d}.{month + 1:02d}.{year}"

