public String dayOfProgrammer(int year) {
    if (year == 1918) {
        return "26.09.1918";                       // transition year
    }
    boolean leap;
    if (year < 1918) {
        leap = year % 4 == 0;                      // Julian
    } else {
        leap = year % 400 == 0 || (year % 4 == 0 && year % 100 != 0);  // Gregorian
    }
    return (leap ? "12" : "13") + ".09." + year;
}

